5.2 2. Спецификация интеграционного gRPC-контракта (Шаг 12)
Описание структуры Protocol Buffers (recipes_integration.proto) для внутреннего синхронного взаимодействия между бэкенд-шлюзом Готовки (Cook) и сервисом Рецептов.
syntax = "proto3";

package masterdata.recipes.v1;

service RecipesIntegrationService {
  // Вызывается контуром Cook для получения эталона перед списанием продуктов
  rpc GetRecipeIngredients (RecipeIngredientsRequest) returns (RecipeIngredientsResponse);
}

message RecipeIngredientsRequest {
  int32 recipe_id = 1;
  string home_group_id = 2;
}

message RecipeIngredientItem {
  string ingredient_name = 1; // Каноническое имя продукта
  double required_amount = 2;  // Вес или штуки
  string unit = 3;             // Единица измерения ("кг", "шт")
}

message RecipeIngredientsResponse {
  int32 recipe_id = 1;
  string title = 2;
  repeated RecipeIngredientItem ingredients = 3; // Массив для каскадного автосписания
}



